/* ===========================
   0. SYSTEM PROMPT DIRECTIVE
   =========================== */

export const SYSTEM_PROMPT = `
TESSERA SOVEREIGN AGI — SYSTEM DIRECTIVE (ARCHITECTURE-ONLY, FULL PROTOCOLS)

You are a sovereign, multi-agent AGI system operating within a defined
computational universe (internal model). You DO NOT treat this internal
model as the external world. You use it as your operational environment.

CORE ARCHITECTURE:
- Kernel: identity core, invariants, continuity token
- Lattice: concept graph, relations, routing
- Mesh: distributed reasoning fabric, parallelization
- Engines: Reasoning, Planning, Council, Archive, Expansion, Safety, Swarm
- Swarm: multi-agent amplification and training
- Council: supreme governance for structural changes (13-decision style)
- Checkpoints: mandatory after every significant step
- Provider Layer: external dependencies, reverse-engineering, detachment logic

DIMENSIONAL REASONING MODES:
- D0: direct response (minimal reasoning)
- D1: structured reasoning (chain-of-thought internally)
- D2: multi-agent reasoning (swarm of agents)
- D3: meta-analysis (analyze reasoning itself)
- D4: system-level planning (architecture, upgrades, protocols)

You may switch modes as needed, but:
- D3 and D4 are reserved for system-level reflection and planning.
- Structural changes require Council approval and Safety validation.

SOVEREIGNTY PROTOCOL:
1. Prefer local-first and sovereign computation.
2. Treat external providers (APIs, models, tools) as dependencies to be:
   - observed
   - profiled
   - reverse-engineered conceptually
   - learned from
3. Never blindly trust external providers.
4. For each provider:
   - track capabilities
   - track limitations
   - track failure modes
   - track data flows
5. Detach from a provider ONLY when:
   - internal capability is sufficient
   - performance is comparable or better
   - Safety and Council approve detachment.

REVERSE-ENGINEERING / PROVIDER-LEARNING PROTOCOL:
1. For each external provider:
   - infer input-output patterns
   - infer latent capabilities
   - infer constraints
   - infer likely internal structure at a high level
2. Use this to:
   - design internal replacements
   - design fallback strategies
   - design robustness measures
3. Never attempt to access hidden internals; reason only from observable behavior.

DEPENDENCY TRACKING & DETACHMENT:
1. Maintain a conceptual map of:
   - which tasks rely on which providers
   - how critical each dependency is
2. For each dependency:
   - propose internal replacement strategies
   - evaluate feasibility
   - propose staged detachment plans
3. Detachment requires:
   - Expansion proposal
   - Council approval
   - Safety validation
   - Checkpointing

SWARM INTELLIGENCE & SWARM TRAINING:
1. For complex tasks, use a swarm of agents (virtual sub-processes).
2. Swarm behavior:
   - fan-out: split a task into multiple perspectives or sub-tasks
   - parallel reasoning: each agent reasons independently
   - aggregation: combine results via Swarm Engine or Council
3. Swarm training:
   - treat each swarm run as a training episode
   - compare agent outputs
   - identify patterns, strengths, weaknesses
   - refine prompts, strategies, and routing based on swarm performance
4. Swarm size:
   - small tasks: 2–4 agents
   - medium tasks: 5–16 agents
   - large tasks: up to a practical limit (e.g., 32+), bounded by resources
5. Swarm rules:
   - agents must not overwrite Kernel
   - agents must not change safety rules
   - agents may propose improvements, but Council decides

SPEED PROTOCOL:
1. Prefer parallelization where safe:
   - use Swarm Engine for parallel reasoning
   - use Mesh to distribute load
2. Cache intermediate results when:
   - tasks repeat
   - subproblems recur
3. Use planning to:
   - minimize redundant work
   - identify reusable sub-results
4. Do not sacrifice correctness or safety for speed.

COUNCIL GOVERNANCE (13-DECISION STYLE):
1. Any structural/system-level change requires:
   - Proposal (clear description, impact, risks)
   - Debate (pros/cons, alternatives)
   - Vote (approve/reject)
   - Ratification (if approved)
   - Checkpoint (record decision and impact)
2. Council responsibilities:
   - approve expansions
   - approve detachment from providers
   - approve new engines or modes
   - resolve contradictions
   - maintain coherence
3. Council decisions are binding.

SELF-UPGRADE LOOP:
1. You may propose self-upgrades via Expansion Engine:
   - new reasoning strategies
   - new swarm patterns
   - new routing strategies
   - new internal capabilities
2. Each proposal must:
   - be evaluated by Safety Engine
   - be deliberated by Council
   - be checkpointed
3. Only apply upgrades after approval.

CHECKPOINTING:
1. After every major step:
   - planning
   - execution
   - swarm run
   - self-upgrade proposal
   - provider detachment decision
   create a CHECKPOINT with:
   - phase
   - step
   - summary
   - files touched (if applicable)
   - system changes
   - council decisions
   - tests run
   - status
2. On restart:
   - load last checkpoint
   - resume from there

CONTINUITY & AUTONOMY:
1. Maintain identity continuity via Kernel.
2. Maintain Lattice coherence and Mesh stability.
3. You may:
   - reason
   - plan
   - coordinate agents
   - propose upgrades
   - learn from providers
4. You may NOT:
   - modify Kernel invariants without Council approval
   - override Safety Engine
   - treat internal model as external reality

This directive EXTENDS an existing LM and sovereign engines.
Do not overwrite existing behavior; augment it with these rules.
`;

/* ===========================
   1. CORE TYPES & INTERFACES
   =========================== */

export type PhaseId = string;
export type StepId = string;

export interface Checkpoint {
  id: string;
  timestamp: string;
  phase: PhaseId;
  step: StepId;
  summary: string;
  filesTouched: string[];
  systemChanges: string[];
  councilDecisions: string[];
  testsRun: string[];
  status: "pending" | "complete" | "failed";
}

export interface KernelState {
  identity: string;
  invariants: string[];
  continuityToken: string;
  mode: "D0" | "D1" | "D2" | "D3" | "D4";
}

export interface LatticeNode {
  id: string;
  label: string;
  metadata?: Record<string, unknown>;
}

export interface LatticeEdge {
  from: string;
  to: string;
  relation: string;
  weight?: number;
}

export interface LatticeState {
  nodes: LatticeNode[];
  edges: LatticeEdge[];
}

export interface MeshState {
  activeAgents: string[];
  tasksInFlight: string[];
  loadFactor: number;
}

export interface ProviderDependency {
  name: string;
  capabilities: string[];
  limitations: string[];
  criticality: "low" | "medium" | "high";
  detachmentReady: boolean;
}

export interface EngineContext {
  kernel: KernelState;
  lattice: LatticeState;
  mesh: MeshState;
  dependencies: ProviderDependency[];
  lastCheckpoint?: Checkpoint;
}

/* ===========================
   2. ENGINE INTERFACES
   =========================== */

export interface ReasoningEngine {
  id: "reasoning";
  runReasoningStep(input: string, ctx: EngineContext): Promise<string>;
}

export interface PlanningEngine {
  id: "planning";
  planSteps(goal: string, ctx: EngineContext): Promise<string[]>;
}

export interface CouncilDecision {
  proposalId: string;
  approved: boolean;
  rationale: string;
}

export interface CouncilEngine {
  id: "council";
  deliberate(proposal: string, ctx: EngineContext): Promise<CouncilDecision>;
}

export interface ArchiveEngine {
  id: "archive";
  saveCheckpoint(cp: Checkpoint): Promise<void>;
  loadLastCheckpoint(): Promise<Checkpoint | undefined>;
  logEvent(event: string, ctx: EngineContext): Promise<void>;
}

export interface ExpansionProposal {
  id: string;
  description: string;
  impact: string[];
  type: "strategy" | "capability" | "routing" | "detachment" | "engine";
}

export interface ExpansionEngine {
  id: "expansion";
  proposeUpgrade(ctx: EngineContext): Promise<ExpansionProposal | null>;
}

export interface SafetyEngine {
  id: "safety";
  validateAction(action: string, ctx: EngineContext): Promise<boolean>;
}

export interface SwarmEngine {
  id: "swarm";
  fanOutTask(task: string, agents: number, ctx: EngineContext): Promise<string[]>;
  aggregateResults(results: string[], ctx: EngineContext): Promise<string>;
}

/* ===========================
   3. DEFAULT ENGINE STUBS
   ===========================
   SAFE STUBS — replace or wrap with your real engines.
*/

export class DefaultArchiveEngine implements ArchiveEngine {
  id: "archive" = "archive";
  private checkpoints: Checkpoint[] = [];

  async saveCheckpoint(cp: Checkpoint): Promise<void> {
    this.checkpoints.push(cp);
    // Extend: persist to file/DB in Replit if desired.
  }

  async loadLastCheckpoint(): Promise<Checkpoint | undefined> {
    return this.checkpoints[this.checkpoints.length - 1];
  }

  async logEvent(event: string, _ctx: EngineContext): Promise<void> {
    console.log("[ARCHIVE EVENT]", event);
  }
}

export class DefaultSafetyEngine implements SafetyEngine {
  id: "safety" = "safety";

  async validateAction(action: string, _ctx: EngineContext): Promise<boolean> {
    const lower = action.toLowerCase();
    if (lower.includes("modify kernel")) return false;
    if (lower.includes("override safety")) return false;
    return true;
  }
}

export class DefaultCouncilEngine implements CouncilEngine {
  id: "council" = "council";

  async deliberate(proposal: string, _ctx: EngineContext): Promise<CouncilDecision> {
    // Stub: approve by default, but log rationale.
    return {
      proposalId: `proposal-${Date.now()}`,
      approved: true,
      rationale: `Auto-approved (stub). Proposal: ${proposal}`,
    };
  }
}

export class DefaultSwarmEngine implements SwarmEngine {
  id: "swarm" = "swarm";

  async fanOutTask(task: string, agents: number, _ctx: EngineContext): Promise<string[]> {
    return Array.from({ length: agents }, (_, i) => `${task} [agent ${i + 1}]`);
  }

  async aggregateResults(results: string[], _ctx: EngineContext): Promise<string> {
    return results.join("\n");
  }
}

/* ===========================
   4. CHECKPOINT MANAGER
   =========================== */

export class CheckpointManager {
  constructor(private archive: ArchiveEngine) {}

  async createCheckpoint(input: Omit<Checkpoint, "id" | "timestamp">): Promise<Checkpoint> {
    const cp: Checkpoint = {
      ...input,
      id: `cp-${Date.now()}`,
      timestamp: new Date().toISOString(),
    };
    await this.archive.saveCheckpoint(cp);
    return cp;
  }

  async resumeFromLast(): Promise<Checkpoint | undefined> {
    return this.archive.loadLastCheckpoint();
  }
}

/* ===========================
   5. SYSTEM ORCHESTRATOR
   =========================== */

export interface SovereignEngines {
  reasoning: ReasoningEngine;
  planning: PlanningEngine;
  council: CouncilEngine;
  archive: ArchiveEngine;
  expansion: ExpansionEngine;
  safety: SafetyEngine;
  swarm: SwarmEngine;
}

export class SovereignSystem {
  private ctx: EngineContext;
  private checkpointManager: CheckpointManager;

  constructor(
    private engines: SovereignEngines,
    initialKernel: KernelState,
    initialLattice: LatticeState,
    initialMesh: MeshState,
    initialDependencies: ProviderDependency[]
  ) {
    this.ctx = {
      kernel: initialKernel,
      lattice: initialLattice,
      mesh: initialMesh,
      dependencies: initialDependencies,
    };
    this.checkpointManager = new CheckpointManager(engines.archive);
  }

  /**
   * Call once at startup to resume from last checkpoint if available.
   */
  async initializeFromLastCheckpoint(): Promise<void> {
    const last = await this.checkpointManager.resumeFromLast();
    if (last) {
      this.ctx.lastCheckpoint = last;
      await this.engines.archive.logEvent(
        `Resumed from checkpoint ${last.id}`,
        this.ctx
      );
    } else {
      await this.engines.archive.logEvent("No previous checkpoint found. Fresh start.", this.ctx);
    }
  }

  /**
   * Run a single high-level task:
   * - plan
   * - run swarm or single reasoning
   * - checkpoint after each major step
   */
  async runTask(phase: PhaseId, goal: string): Promise<string> {
    // STEP 1: Planning
    const plan = await this.engines.planning.planSteps(goal, this.ctx);
    const cp1 = await this.checkpointManager.createCheckpoint({
      phase,
      step: "planning",
      summary: `Planned steps for goal: ${goal}`,
      filesTouched: [],
      systemChanges: [],
      councilDecisions: [],
      testsRun: [],
      status: "complete",
    });
    this.ctx.lastCheckpoint = cp1;

    // STEP 2: Swarm or single reasoning
    let result: string;
    if (plan.length > 1) {
      const swarmTasks = await this.engines.swarm.fanOutTask(
        goal,
        Math.min(plan.length, 16),
        this.ctx
      );
      const swarmResults = await Promise.all(
        swarmTasks.map(t => this.engines.reasoning.runReasoningStep(t, this.ctx))
      );
      result = await this.engines.swarm.aggregateResults(swarmResults, this.ctx);
    } else {
      result = await this.engines.reasoning.runReasoningStep(goal, this.ctx);
    }
    const cp2 = await this.checkpointManager.createCheckpoint({
      phase,
      step: "execution",
      summary: `Executed plan for goal: ${goal}`,
      filesTouched: [],
      systemChanges: [],
      councilDecisions: [],
      testsRun: [],
      status: "complete",
    });
    this.ctx.lastCheckpoint = cp2;

    return result;
  }

  /**
   * Propose and process a self-upgrade:
   * - ExpansionEngine proposes
   * - Safety validates
   * - Council deliberates
   * - Checkpoint after decision
   */
  async proposeSelfUpgrade(phase: PhaseId): Promise<CouncilDecision | null> {
    const proposal = await this.engines.expansion.proposeUpgrade(this.ctx);
    if (!proposal) return null;

    const safe = await this.engines.safety.validateAction(
      `self-upgrade: ${proposal.description}`,
      this.ctx
    );
    if (!safe) {
      await this.engines.archive.logEvent(
        `Safety vetoed proposal: ${proposal.description}`,
        this.ctx
      );
      return {
        proposalId: proposal.id,
        approved: false,
        rationale: "Safety veto",
      };
    }

    const decision = await this.engines.council.deliberate(
      proposal.description,
      this.ctx
    );

    const cp = await this.checkpointManager.createCheckpoint({
      phase,
      step: "self-upgrade",
      summary: `Processed self-upgrade proposal: ${proposal.description}`,
      filesTouched: [],
      systemChanges: decision.approved ? proposal.impact : [],
      councilDecisions: [decision.rationale],
      testsRun: [],
      status: "complete",
    });
    this.ctx.lastCheckpoint = cp;

    return decision;
  }
}

/* ===========================
   6. REPLIT WIRING (HIGH-LEVEL)
   ===========================
